    var CURSOR_POS_EXP = new RegExp(":([^,:]+)?([,:](.+)?)?");

    /**
     * Current plugin
     * @private
     * @type {QuickOpenPlugin}
     */
    var currentPlugin = null;

    /**
     *  @type {Array.<File>}
     *  @private
     */
    var fileList;

    /**
     * @type {$.Promise}
     * @private
     */
    var fileListPromise;

